# select uses SHA256 two 53-bit draws, sorted unique IDs, band weights then uniform index.
def select(candidates,weights,seed):
 cs=sorted(set(candidates));bands=[[q for q in cs if ratings[q]==b] for b in ('easy','moderate','hard')];unrated=[q for q in cs if ratings[q] is None]
 if weights is None:return cs[0] if cs else None
 dig=hashlib.sha256(('course-academy/question-selection/v1/'+seed).encode()).digest()
 uniform=lambda off:(int.from_bytes(dig[off:off+8],'big')>>11)/(1<<53)
 total=sum(w for w,band in zip(weights,bands) if band)
 if total>0:
  draw=uniform(0)*total;pool=[]
  for w,band in zip(weights,bands):
   if not band or w==0:continue
   pool=band
   if draw<w:break
   draw-=w
 else:pool=unrated
 return pool[int(uniform(8)*len(pool))] if pool else None
